      "html_structure": "<div class=\"conversation-list p-4 bg-gray-50 h-full overflow-y-auto\"> <h3 class=\"font-semibold mb-2\">Conversations</h3> <ul> <template x-for=\"(conversation, index) in conversations\" :key=\"conversation.id\"> <li @click=\"switchConversation(conversation.id)\" class=\"p-2 hover:bg-gray-100 rounded cursor-pointer\" :class=\"{ 'bg-blue-100': conversation.id === currentConversationId }\" x-text=\"conversation.title\"></li> </template> </ul> </div>",
      "alpine_js_data": {
