      "html_structure": "<div class=\"settings-panel p-4 bg-gray-50 h-full overflow-y-auto\"> <h3 class=\"font-semibold mb-2\">Settings</h3> <div class=\"mb-4\"> <label class=\"block text-sm font-medium text-gray-700\">Theme</label> <select x-model=\"theme\" class=\"mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-md\"> <option value=\"light\">Light</option> <option value=\"dark\">Dark</option> </select> </div> <button @click=\"saveSettings\" class=\"bg-blue-500 text-white px-4 py-2 rounded\">Save Settings</button> </div>",
      "alpine_js_data": {
