      "html_structure": "<div class=\"agent-selector p-4 bg-gray-50 h-full overflow-y-auto\"> <h3 class=\"font-semibold mb-2\">Agents</h3> <ul> <template x-for=\"(agent, index) in agents\" :key=\"agent.id\"> <li @click=\"selectAgent(agent.id)\" class=\"p-2 hover:bg-gray-100 rounded cursor-pointer\" x-text=\"agent.name\"></li> </template> </ul> </div>",
      "alpine_js_data": {
        "agents": "array of {id, name, description}",
        "selectedAgentId": "uuid"
