      "html_structure": "<div class=\"agent-form p-4 bg-gray-50 h-full overflow-y-auto\"> <h3 class=\"font-semibold mb-2\" x-text=\"selectedAgent?.name\"></h3> <form @submit.prevent=\"executeAgent\"> <template x-for=\"(field, index) in selectedAgent?.fields\" :key=\"index\"> <div class=\"mb-4\"> <label class=\"block text-sm font-medium text-gray-700\" x-text=\"field.label\"></label> <input :type=\"field.type\" x-model=\"agentInputs[field.name]\" class=\"mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm\"> </div> </template> <button type=\"submit\" class=\"bg-green-500 text-white px-4 py-2 rounded\">Execute Agent</button> </form> </div>",
      "alpine_js_data": {
        "selectedAgent": "{id, name, fields: [{name, label, type}]}",
        "agentInputs": "object with field names as keys"
      },
      "alpine_js_methods": [
        "executeAgent() - POST /api/agents/execute"
      ],
      "tailwind_classes": ["p-4", "bg-gray-50", "h-full", "overflow-y-auto"],
      "api_interactions": [
        "POST /api/agents/execute"
      ]
    },
    {
      "name": "agent_status_indicator",
      "type": "interactive",
      "description": "Status bar showing current agent execution status with stop/cancel controls",
      "html_structure": "<div class=\"agent-status-indicator p-2 bg-gray-100 border-t border-gray-300 flex items-center justify-between\"> <div> <span x-text=\"agentStatus\"></span> <span x-show=\"isAgentRunning\" class=\"ml-2 text-green-500\">Running...</span> </div> <div> <button x-show=\"isAgentRunning\" @click=\"cancelAgent\" class=\"bg-red-500 text-white px-3 py-1 rounded text-sm\">Cancel</button> </div> </div>",
      "alpine_js_data": {
        "agentStatus": "string",
        "isAgentRunning": "boolean"
      },
      "alpine_js_methods": [
        "cancelAgent() - POST /api/agents/cancel"
      ],
      "tailwind_classes": ["p-2", "bg-gray-100", "border-t", "border-gray-300", "flex", "items-center", "justify-between"],
      "api_interactions": [
        "POST /api/agents/cancel"
      ]
    }
  ],
  "page_layouts": [
    {
