  "frontend_framework": "alpine_tailwind",
  "state_management": {
    "method": "Alpine.store for global state",
    "stores": {
      "auth": "user authentication state",
      "chat": "current conversation and messages",
      "agents": "available agents and execution status"
    }
  },
  "api_endpoints": [
    {
      "method": "POST",
      "path": "/api/chat/send",
      "description": "Send user message and initiate LLM response",
      "request_body": {
        "fields": [
          {
            "name": "message",
            "type": "string",
            "required": true,
            "max_length": 4000
          },
          {
            "name": "conversation_id",
            "type": "uuid",
            "required": false
          }
        ]
      },
      "response": {
        "status_code": 201,
        "body": {
          "message_id": "uuid",
          "conversation_id": "uuid",
          "stream_url": "/api/chat/stream/{message_id}"
        }
      },
      "auth_required": true,
      "rate_limit": "10 per minute per user"
    },
    {
      "method": "GET",
      "path": "/api/chat/stream/{message_id}",
      "description": "Stream LLM response chunks via Server-Sent Events",
      "query_params": [
        {
          "name": "message_id",
          "type": "uuid",
          "required": true
        }
      ],
      "response": {
        "content_type": "text/event-stream",
        "event_format": "data: {\"chunk\": \"text\", \"done\": false}\n\n"
      },
      "auth_required": true
    },
    {
      "method": "POST",
      "path": "/api/chat/regenerate",
      "description": "Regenerate the last assistant response",
      "request_body": {
        "fields": [
          {
            "name": "message_id",
            "type": "uuid",
            "required": true
          }
        ]
      },
      "response": {
        "status_code": 200,
        "body": {
          "message_id": "uuid",
          "stream_url": "/api/chat/stream/{message_id}"
        }
      },
      "auth_required": true
    },
    {
      "method": "POST",
      "path": "/api/files/upload",
      "description": "Upload a file for chat attachment or agent input",
      "request_body": {
        "fields": [
          {
            "name": "file",
            "type": "file",
            "required": true
          }
        ]
      },
      "response": {
        "status_code": 201,
        "body": {
          "file_id": "uuid",
          "file_url": "/api/files/{file_id}"
        }
      },
      "auth_required": true
    },
    {
      "method": "GET",
      "path": "/api/conversations",
      "description": "Get list of user's conversations",
      "response": {
        "status_code": 200,
        "body": {
          "conversations": [
            {
              "id": "uuid",
              "title": "string",
              "created_at": "datetime"
            }
          ]
        }
      },
      "auth_required": true
    },
    {
      "method": "GET",
      "path": "/api/conversations/{id}",
      "description": "Get specific conversation with messages",
      "response": {
        "status_code": 200,
        "body": {
          "id": "uuid",
          "title": "string",
          "created_at": "datetime",
          "messages": [
            {
              "role": "string",
              "content": "string",
              "timestamp": "datetime"
            }
          ]
        }
      },
      "auth_required": true
    },
    {
      "method": "POST",
      "path": "/api/settings",
      "description": "Save user settings",
      "request_body": {
        "fields": [
          {
            "name": "theme",
            "type": "string",
            "required": false
          }
        ]
      },
      "response": {
        "status_code": 200,
        "body": {
          "message": "Settings saved"
        }
      },
      "auth_required": true
    },
    {
      "method": "POST",
      "path": "/api/auth/logout",
      "description": "Logout current user",
      "response": {
        "status_code": 200,
        "body": {
          "message": "Logged out"
        }
      },
      "auth_required": true
    },
    {
      "method": "GET",
      "path": "/api/agents",
      "description": "Get list of available agents",
      "response": {
        "status_code": 200,
        "body": {
          "agents": [
            {
              "id": "uuid",
              "name": "string",
              "description": "string",
              "fields": [
                {
                  "name": "string",
                  "label": "string",
                  "type": "string"
                }
              ]
            }
          ]
        }
      },
      "auth_required": true
    },
    {
      "method": "POST",
      "path": "/api/agents/execute",
      "description": "Execute a selected agent with provided inputs",
      "request_body": {
        "fields": [
          {
            "name": "agent_id",
            "type": "uuid",
            "required": true
          },
          {
            "name": "inputs",
            "type": "object",
            "required": true
          }
        ]
      },
      "response": {
        "status_code": 202,
        "body": {
          "execution_id": "uuid",
          "status": "string"
        }
      },
      "auth_required": true
    },
    {
      "method": "POST",
      "path": "/api/agents/cancel",
      "description": "Cancel a running agent execution",
      "request_body": {
        "fields": [
          {
            "name": "execution_id",
            "type": "uuid",
            "required": true
          }
        ]
      },
      "response": {
        "status_code": 200,
        "body": {
          "message": "Agent execution cancelled"
        }
      },
      "auth_required": true
    }
  ],
