  "authentication": {
    "method": "JWT",
    "token_expiry": "30 minutes",
    "refresh_token_expiry": "7 days",
    "password_hashing": "bcrypt with 12 rounds"
  },
  "authorization": {
    "method": "role_based",
    "roles": ["user", "admin"],
    "permissions": {
      "user": ["read_own_data", "write_own_data"],
      "admin": ["read_all_data", "write_all_data", "manage_users"]
    }
  },
  "data_flows": [
    {
      "name": "Send Chat Message Flow",
      "steps": [
        {
          "step": 1,
          "action": "User types message and clicks send"
        },
        {
          "step": 2,
          "action": "Frontend validates (non-empty, max 4000 chars)"
        },
        {
          "step": 3,
          "action": "POST /api/chat/send with message and conversation_id"
        },
        {
          "step": 4,
          "action": "Backend validates authentication"
        },
        {
          "step": 5,
          "action": "Backend creates Message record with role='user'"
        },
        {
          "step": 6,
          "action": "Backend initiates LLM API call"
        },
        {
          "step": 7,
          "action": "Backend returns message_id and stream_url"
        },
        {
          "step": 8,
          "action": "Frontend opens EventSource to stream_url"
        },
        {
          "step": 9,
          "action": "Backend streams LLM response chunks"
        },
        {
          "step": 10,
          "action": "Frontend appends chunks to display"
        },
        {
          "step": 11,
          "action": "On stream complete, backend saves assistant Message"
        },
        {
          "step": 12,
          "action": "Frontend updates UI with complete message"
        }
      ],
      "error_handling": [
        "Validation errors: Show inline error message",
        "Network errors: Retry with exponential backoff",
        "LLM errors: Show 'Unable to generate response' with retry button",
        "Auth errors: Redirect to login"
      ]
    },
    {
      "name": "Execute Agent Flow",
      "steps": [
        {
          "step": 1,
          "action": "User selects agent and fills form"
        },
        {
          "step": 2,
          "action": "Frontend validates form inputs"
        },
        {
          "step": 3,
          "action": "POST /api/agents/execute with agent_id and inputs"
        },
        {
          "step": 4,
          "action": "Backend validates authentication"
        },
        {
          "step": 5,
          "action": "Backend creates AgentExecution record with status='pending'"
        },
        {
          "step": 6,
          "action": "Backend queues agent execution in background worker"
        },
        {
          "step": 7,
          "action": "Backend returns execution_id"
        },
        {
          "step": 8,
          "action": "Frontend updates agent status indicator"
        },
        {
          "step": 9,
          "action": "Background worker executes agent"
        },
        {
          "step": 10,
          "action": "On completion, worker updates AgentExecution status and outputs"
        },
        {
          "step": 11,
          "action": "Backend sends email notification to user"
        },
        {
          "step": 12,
          "action": "Frontend updates agent status indicator to complete"
        }
      ],
      "error_handling": [
        "Validation errors: Show form validation errors",
        "Agent execution errors: Update status to 'failed' with error message",
        "Network errors: Retry agent execution with exponential backoff",
        "Auth errors: Redirect to login"
      ]
    }
  ],
  "database_type": "postgresql",
  "caching_strategy": {
    "enabled": true,
    "backend": "redis",
    "cache_items": [
      "user sessions (TTL: 30min)",
      "conversation summaries (TTL: 1hour)",
      "agent metadata (TTL: 5min)"
    ]
  },
  "background_workers": [
    {
      "name": "agent_executor",
      "trigger": "on_demand",
      "description": "Execute agent tasks in background",
      "parameters": ["agent_name", "input_data", "user_id"]
    }
  ],
  "external_integrations": [
    {
      "name": "OpenAI API",
      "purpose": "LLM chat completions",
      "endpoints": ["https://api.openai.com/v1/chat/completions"],
      "authentication": "Bearer token in Authorization header",
      "rate_limits": "Handle 429 responses with exponential backoff"
    },
    {
      "name": "Flask Server",
      "purpose": "Agent execution and orchestration",
      "base_url": "http://localhost:5000",
      "endpoints": ["/api/agents/list", "/api/agents/execute"],
      "authentication": "API key in X-API-Key header"
    }
